import{_ as e,o as s,c as i,ag as a}from"./chunks/framework.DNmTgtHf.js";const u=JSON.parse('{"title":"Part 19 — Authorization","description":"","frontmatter":{},"headers":[],"relativePath":"todo/study_plan/parts/Part_19_Authorization.md","filePath":"todo/study_plan/parts/Part_19_Authorization.md"}'),r={name:"todo/study_plan/parts/Part_19_Authorization.md"};function n(o,t,d,l,c,h){return s(),i("div",null,[...t[0]||(t[0]=[a(`<h1 id="part-19-—-authorization" tabindex="-1">Part 19 — Authorization <a class="header-anchor" href="#part-19-—-authorization" aria-label="Permalink to &quot;Part 19 — Authorization&quot;">​</a></h1><blockquote><p><strong>Sprint allocation:</strong> Week 9 (shared). <strong>Budget: ~3-4 hrs.</strong></p></blockquote><h2 id="_19-authorization-—-topic-inventory" tabindex="-1">19 Authorization — topic inventory <a class="header-anchor" href="#_19-authorization-—-topic-inventory" aria-label="Permalink to &quot;19 Authorization — topic inventory&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>Topic</th><th>Tags</th><th>Tier</th><th>Time</th><th>Done</th><th>Partial</th><th>Grilling</th><th>Visit Again</th><th>Notes</th><th>Resources</th></tr></thead><tbody><tr><td>1</td><td>RBAC — roles, permissions, hierarchies</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1 hr 50 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: model TenantAdmin/Agent/Viewer roles + write @PreAuthorize annotations on 3 endpoints (20 min)</td></tr><tr><td>2</td><td>ABAC — attribute-based, policies</td><td>🔴 💼 🔐 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>3</td><td>Spring Security architecture — filter chain, SecurityContext, @PreAuthorize internals</td><td>🔴 💼 🎯</td><td>MP</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: trace one request through SecurityFilterChain — DEBUG log + identify the 5 default filters in order (30 min)</td></tr><tr><td>4</td><td>JWT claim → GrantedAuthority mapping in Spring Security</td><td>🔴 💼 🎯</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>5</td><td>ACL — direct permissions on resources</td><td>🔴 💼 🔐 🎯</td><td>M</td><td>45 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>6</td><td>OAuth scopes vs roles vs permissions — the distinction</td><td>🔴 💼 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>7</td><td>ReBAC — Google Zanzibar model, SpiceDB, OpenFGA</td><td>🟠 💼 🔐</td><td>MP</td><td>2 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>8</td><td>PBAC (policy-based) — OPA / Rego, Cedar</td><td>🟠 💼 🔐</td><td>MP</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: write a Rego policy that denies cross-tenant access (30 min)</td></tr><tr><td>9</td><td>Multi-tenant authorization — tenant isolation</td><td>🟠 💼 🔐</td><td>D</td><td>2.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>10</td><td>Row-level security (RLS) in DBs</td><td>🟠 💼 🔐</td><td>MP</td><td>1 hr 50 min</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td>💻 Warm-up: Postgres CREATE POLICY + session-var (SET app.tenant_id) + test cross-tenant query rejection (20 min)</td></tr><tr><td>11</td><td>Method-level + URL-level + data-level authorization — defense in depth</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>12</td><td>Audit logging of authz decisions — who tried to access what, when, denied or allowed</td><td>🟠 💼 🔐</td><td>MP</td><td>1.5 hrs</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>13</td><td>Permission caching + TTL — authz checks per request are expensive; how to cache safely</td><td>🟠 💼</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr><tr><td>14</td><td>Step-up authentication for sensitive ops</td><td>🟠 🔐</td><td>M</td><td>1 hr</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td>[ ]</td><td></td><td></td></tr></tbody></table><h2 id="time-summary" tabindex="-1">Time summary <a class="header-anchor" href="#time-summary" aria-label="Permalink to &quot;Time summary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Scope</th><th>Hours (zero baseline)</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>🔴 MUST only (Sprint priority — 3-month plan)</td><td>~9 hrs</td><td>~0.82 wk</td><td></td></tr><tr><td>🔴 + 🟠 HIGH (must + high — senior coverage)</td><td>~22 hrs</td><td>~2 wk</td><td></td></tr><tr><td>Full Part (all items — no 🟡 in this Part)</td><td>~22 hrs</td><td>~2 wk</td><td></td></tr></tbody></table><h2 id="key-diagrams" tabindex="-1">Key diagrams <a class="header-anchor" href="#key-diagrams" aria-label="Permalink to &quot;Key diagrams&quot;">​</a></h2><p><strong>RBAC vs ABAC vs ReBAC — which model fits the problem:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart TD</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Start[Authorization decision needed] --&gt; Q1{Permissions depend on&lt;br/&gt;user identity only?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Q1 -- yes --&gt; RBAC[RBAC&lt;br/&gt;Roles + role-permission mapping&lt;br/&gt;Examples: TenantAdmin, Agent, Viewer&lt;br/&gt;Sweet spot: small role set, predictable]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Q1 -- no --&gt; Q2{Permissions depend on&lt;br/&gt;context — time, IP, attributes?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Q2 -- yes --&gt; ABAC[ABAC&lt;br/&gt;Policies over user/resource/env attrs&lt;br/&gt;Examples: deny after-hours, restrict by IP,&lt;br/&gt;allow only doc.owner == user.id&lt;br/&gt;Sweet spot: contextual rules]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Q2 -- no --&gt; Q3{Permissions follow&lt;br/&gt;object relationships —&lt;br/&gt;owns, member-of, shared-with?}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Q3 -- yes --&gt; ReBAC[ReBAC — Zanzibar/OpenFGA&lt;br/&gt;Relationship tuples + graph walk&lt;br/&gt;Examples: user can view doc if member&lt;br/&gt;of any parent folder&lt;br/&gt;Sweet spot: Drive/GitHub-style sharing]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Q3 -- no --&gt; Hybrid[Likely hybrid&lt;br/&gt;RBAC + ABAC layered, or PBAC engine — OPA]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style RBAC fill:#cfe</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style ABAC fill:#fec</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style ReBAC fill:#cef</span></span></code></pre></div><blockquote><p>Most production systems layer RBAC (coarse role gate) + ABAC (contextual rules) + ReBAC (relationship graph) — pick the dominant model first, layer the others where needed.</p></blockquote><p><strong>Defense-in-depth authorization layers — which bug each layer catches:</strong></p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Req[Request] --&gt; URL[URL filter&lt;br/&gt;SecurityFilterChain&lt;br/&gt;Coarse: logged in? has role?]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    URL --&gt; Method[Method-level&lt;br/&gt;@PreAuthorize&lt;br/&gt;Fine: permission for this op?]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Method --&gt; Svc[Service logic&lt;br/&gt;Business rule check&lt;br/&gt;e.g., order.user == currentUser]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Svc --&gt; Data[Data-level&lt;br/&gt;RLS / WHERE tenant_id&lt;br/&gt;Last-line safety net]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Data --&gt; DB[(DB)]</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    URL -.catches.-&gt; B1[Anonymous access&lt;br/&gt;to protected URL]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Method -.catches.-&gt; B2[Logged-in user&lt;br/&gt;calling wrong-role op]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Svc -.catches.-&gt; B3[IDOR — accessing&lt;br/&gt;another user&#39;s resource]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Data -.catches.-&gt; B4[Bug in code above&lt;br/&gt;leaking cross-tenant rows]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style B1 fill:#fdd</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style B2 fill:#fdd</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style B3 fill:#fdd</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    style B4 fill:#fdd</span></span></code></pre></div><blockquote><p>No single layer is sufficient. URL filter alone fails open on IDOR; method-level alone fails open on cross-tenant queries. Each layer is a different class of guarantee.</p></blockquote><h2 id="frequently-asked" tabindex="-1">Frequently asked <a class="header-anchor" href="#frequently-asked" aria-label="Permalink to &quot;Frequently asked&quot;">​</a></h2><ol><li><strong>Q:</strong> RBAC vs ABAC vs ReBAC — when does each fit? <ul><li><strong>Why asked:</strong> Architecture decision. RBAC: small set of roles, predictable permissions per role. Simple, scales for most apps. ABAC: attribute-based, more expressive — fits when permissions depend on context (time, IP, resource owner). ReBAC: relationship-based, fits when permissions follow object graphs (e.g., &quot;can view document if member of any folder containing it&quot;). Multi-tenant SaaS often layers RBAC + ABAC + ReBAC.</li></ul></li><li><strong>Q:</strong> OAuth scope vs role — same thing or different? <ul><li><strong>Why asked:</strong> Common confusion. Scope: what the <em>token</em> is authorized for (e.g., <code>read:profile</code>, <code>write:orders</code>). Granted at token-issue time. Role: what the <em>user</em> is (e.g., admin, customer). Persistent. Token scopes are typically a subset of user&#39;s permissions (least-privilege per session). Permissions are the fine-grained capabilities at the resource level.</li></ul></li><li><strong>Q:</strong> Multi-tenant authorization — how do you guarantee Tenant A never sees Tenant B&#39;s data? <ul><li><strong>Why asked:</strong> SaaS-canonical. Defense in depth: (1) tenant_id in every query (WHERE clause), enforced by repository abstraction or RLS, (2) tenant_id derived from JWT claim, not request param, (3) audit logging of cross-tenant access attempts, (4) per-tenant DB / schema for highest-tier customers (cellular isolation).</li></ul></li><li><strong>Q:</strong> Where do you enforce authorization — at the controller, service, or DB? <ul><li><strong>Why asked:</strong> Defense in depth. All three: (1) URL-level (filter / middleware) — coarse-grained &quot;logged in, has role&quot;. (2) Method-level (<code>@PreAuthorize</code> in Spring) — fine-grained &quot;this method needs permission X&quot;. (3) Data-level (RLS or <code>WHERE tenant_id=...</code>) — last line, catches bugs in code above. One layer can&#39;t be trusted alone.</li></ul></li><li><strong>Q:</strong> OPA / Rego — when does PBAC make sense? <ul><li><strong>Why asked:</strong> Modern authorization. PBAC: externalized policy engine, declarative rules. Worth it when (1) policies change frequently (without redeploy), (2) policies span multiple services (consistent across), (3) compliance / audit needs explicit policy documents. Caveats: latency (network hop), policy debugging complexity.</li></ul></li><li><strong>Q:</strong> Step-up authentication — what is it, when do you trigger? <ul><li><strong>Why asked:</strong> Modern UX security. Same user, but elevated MFA required for sensitive operations (e.g., add payment method, change password, large transaction). Triggered: based on risk score (new device, new location, unusual time, high-value action). Implemented via re-prompt + ACR claim in OIDC.</li></ul></li><li><strong>Q:</strong> Your KYC platform has tenant + agent users + admin users. Design the RBAC model. <ul><li><strong>Why asked:</strong> Domain application. Tenant (bank): users who belong to a partner bank. Roles: TenantAdmin (manage bank settings), TenantAgent (process verifications), TenantViewer (read-only). Cross-tenant: PlatformAdmin (your team). Implementation: JWT carries <code>tenant_id</code> + <code>roles[]</code> claims. Authorization checks both.</li></ul></li></ol><h2 id="trick-questions-gotchas" tabindex="-1">Trick questions / gotchas <a class="header-anchor" href="#trick-questions-gotchas" aria-label="Permalink to &quot;Trick questions / gotchas&quot;">​</a></h2><ol><li><strong>Q:</strong> Your method <code>getOrder(orderId)</code> checks <code>if order.userId == currentUser</code>. A bug allows passing any orderId. What&#39;s the fix? <ul><li><strong>Gotcha:</strong> This is IDOR (Insecure Direct Object Reference). Even with the check, the attacker can probe other order IDs to find ones they own. Or worse: the check uses <code>equals()</code> instead of comparing the user ID server-side. Fix: (1) always derive resource owner from server-side context (DB lookup), (2) consider opaque resource IDs (UUIDs instead of sequential), (3) add audit logging of access failures.</li></ul></li><li><strong>Q:</strong> Your @PreAuthorize(&quot;hasRole(&#39;ADMIN&#39;)&quot;) on a public method works in production. But @PreAuthorize on a private method silently doesn&#39;t enforce. Why? <ul><li><strong>Gotcha:</strong> Spring AOP proxy gotcha. Method security is proxy-based; private method calls bypass the proxy. Always public methods. Or use AspectJ weaving. Same trap as @Transactional, @Async, @Cacheable.</li></ul></li><li><strong>Q:</strong> You implemented RLS in Postgres. Queries from your app return all rows anyway. Why? <ul><li><strong>Gotcha:</strong> Likely connecting as a superuser (bypasses RLS), or RLS policy isn&#39;t applied (CREATE POLICY but didn&#39;t ENABLE), or <code>current_setting(&#39;app.tenant_id&#39;)</code> is not being set per-session. Fix: connect with a non-superuser role that has RLS, set the session variable per request via Hibernate interceptor.</li></ul></li><li><strong>Q:</strong> Cross-tenant data leak — you found a bug where Tenant A&#39;s user can see Tenant B&#39;s data. What&#39;s the post-mortem checklist? <ul><li><strong>Gotcha:</strong> Critical incident. (1) Contain: disable the affected endpoint/method. (2) Audit: query logs to identify exposure scope. (3) Notify: regulators (GDPR breach notification within 72h), affected tenants, customers. (4) Fix: code + tests + RLS guardrail. (5) Document: post-mortem with action items.</li></ul></li></ol><h2 id="mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" tabindex="-1">Mastery candidates (top 3–5 from this Part — suggestions, not commitments) <a class="header-anchor" href="#mastery-candidates-top-3–5-from-this-part-—-suggestions-not-commitments" aria-label="Permalink to &quot;Mastery candidates (top 3–5 from this Part — suggestions, not commitments)&quot;">​</a></h2><ul><li><strong>Multi-tenant authorization for your KYC platform</strong> (~2.5 hrs row 7) — directly job-relevant. Walk through tenant_id derivation, RLS guard, audit trail, breach detection.</li><li><strong>Defense-in-depth authorization layers</strong> (~2.5 hrs combined rows 7+8+9) — URL, method, data. Show how each catches a different class of bug.</li><li><strong>ReBAC + Zanzibar model</strong> (~2 hrs row 5) — modern, hot topic at scale. Understand the relationship-graph approach. Compare to RBAC for KYC&#39;s document-access scenarios.</li></ul><h2 id="hands-on-exercises-practice-advanced" tabindex="-1">Hands-on exercises (Practice + Advanced) <a class="header-anchor" href="#hands-on-exercises-practice-advanced" aria-label="Permalink to &quot;Hands-on exercises (Practice + Advanced)&quot;">​</a></h2><p>Warm-up authz exercises are listed inline in the topic-table Resources column (counted in main Time summary). Longer exercises below are tracked separately.</p><h3 id="practice-—-mid-level-30-60-min-each" tabindex="-1">Practice — mid-level (~30-60 min each) <a class="header-anchor" href="#practice-—-mid-level-30-60-min-each" aria-label="Permalink to &quot;Practice — mid-level (~30-60 min each)&quot;">​</a></h3><ol><li><strong>Spring Security multi-role @PreAuthorize demo</strong> (~60 min) — Spring Boot controller with 3 endpoints (admin-only, agent+admin, public). 3 roles wired from JWT claims via a custom <code>JwtAuthenticationConverter</code>. Test matrix: each role calling each endpoint, assert 200 / 403 / 401 as expected. Surface the <code>AccessDeniedException</code> path.</li><li><strong>Postgres RLS with tenant_id session variable</strong> (~60 min) — <code>CREATE POLICY tenant_isolation ON orders USING (tenant_id = current_setting(&#39;app.tenant_id&#39;)::uuid)</code>. Wire a Hibernate interceptor (or <code>@PostConstruct</code> connection initializer) that runs <code>SET app.tenant_id = &#39;...&#39;</code> per request from JWT. Test cross-tenant query → 0 rows returned even when WHERE clause is omitted.</li><li><strong>IDOR vulnerability + fix</strong> (~45 min) — write the buggy <code>getOrder(@RequestParam Long orderId)</code> that trusts the param. Demonstrate the exploit (curl with another tenant&#39;s order id). Then write the fix: derive owner from <code>SecurityContextHolder</code>, server-side ownership check via repo lookup, deny with audit log on mismatch.</li></ol><h3 id="advanced-—-senior-grade-depth-90-min-each" tabindex="-1">Advanced — senior-grade depth (~90+ min each) <a class="header-anchor" href="#advanced-—-senior-grade-depth-90-min-each" aria-label="Permalink to &quot;Advanced — senior-grade depth (~90+ min each)&quot;">​</a></h3><ol start="4"><li><strong>OPA sidecar evaluating Rego policy</strong> (~90 min) — run OPA as a sidecar (Docker). Spring service calls OPA over HTTP for each authz decision. Rego policy enforces multi-tenant + role rules (e.g., &quot;allow if input.user.tenant == input.resource.tenant AND &#39;agent&#39; in input.user.roles&quot;). Compare latency + flexibility against equivalent in-process <code>@PreAuthorize</code>. Document when externalizing policy is worth the network hop.</li><li><strong>ReBAC with OpenFGA</strong> (~120 min) — model document-access relationships (&quot;user can view doc if member of any parent folder, recursively&quot;). Write the FGA schema (<code>type document</code>, <code>relations { viewer, parent }</code>), seed tuples for a 3-level folder tree, query authorization (<code>check</code> API). Compare expressiveness vs equivalent RBAC/ABAC modeling. Note the graph-walk cost characteristics.</li></ol><h3 id="hands-on-time-summary-practice-advanced-only" tabindex="-1">Hands-on time summary (Practice + Advanced only) <a class="header-anchor" href="#hands-on-time-summary-practice-advanced-only" aria-label="Permalink to &quot;Hands-on time summary (Practice + Advanced only)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tier</th><th>Total time</th><th>Weeks @ 10–12 hrs/wk</th><th>Actual time</th></tr></thead><tbody><tr><td>Practice (mid-level)</td><td>~2.75 hrs</td><td>~0.25 wk</td><td></td></tr><tr><td>Advanced (senior-grade)</td><td>~3.5 hrs</td><td>~0.32 wk</td><td></td></tr><tr><td><strong>Combined hands-on (Practice + Advanced)</strong></td><td><strong>~6.25 hrs</strong></td><td><strong>~0.57 wk</strong></td><td></td></tr></tbody></table><blockquote><p>Warm-up exercises (counted in main Time summary above) total ~100 min for Part 19 across 4 in-table warm-ups.</p></blockquote><h2 id="quick-recall" tabindex="-1">Quick recall <a class="header-anchor" href="#quick-recall" aria-label="Permalink to &quot;Quick recall&quot;">​</a></h2><p><strong>Q. RBAC vs ABAC vs ReBAC — pick when each fits.</strong> A. RBAC: predictable roles. ABAC: contextual rules (time, IP, attributes). ReBAC: relationship-graph permissions (e.g., &quot;user can read doc if in any parent folder&quot;).</p><p><strong>Q. Scope vs role — one-line distinction.</strong> A. Scope: what <em>this token</em> is permitted to do (per-session subset of user permissions). Role: what <em>this user</em> is, persistent identity attribute.</p><p><strong>Q. Defense-in-depth authorization layers?</strong> A. URL-level (filter) → method-level (@PreAuthorize) → data-level (RLS or WHERE tenant_id). All three; one alone is brittle.</p><p><strong>Q. IDOR (Insecure Direct Object Reference) — what is it?</strong> A. Authorization bypass where the request includes a resource ID and the server doesn&#39;t verify ownership. Attacker enumerates IDs to access others&#39; data.</p><p><strong>Q. @PreAuthorize on private method — does it work?</strong> A. No — same Spring AOP proxy gotcha as @Transactional/@Async. Private method calls bypass the proxy. Use public methods or AspectJ weaving.</p><p><strong>Q. Step-up auth — when triggered?</strong> A. Risk-based: new device, new location, unusual time, sensitive operation. Re-prompts user for stronger factor (MFA / WebAuthn). ACR claim in OIDC carries the auth context level reached.</p><p><strong>Q. Spring SecurityFilterChain — order of the key default filters?</strong> A. <code>SecurityContextPersistenceFilter</code> → <code>BearerTokenAuthenticationFilter</code> (or <code>UsernamePasswordAuthenticationFilter</code>) → <code>ExceptionTranslationFilter</code> → <code>AuthorizationFilter</code> (formerly <code>FilterSecurityInterceptor</code>). Authentication populates <code>SecurityContext</code>; authorization reads from it. <code>@PreAuthorize</code> runs <em>after</em> the filter chain via method-level AOP proxy, not inside the chain.</p><p><strong>Q. Audit log of authz decisions — what must each entry capture?</strong> A. who (subject ID + tenant), what (resource ID + action), when (timestamp + request ID), decision (allow/deny), reason (which rule/role/policy fired), context (IP, user agent, ACR). Log both allows and denies — denies for security, allows for compliance/forensics. Append-only, immutable storage; deny logs trigger alerting beyond a per-user threshold.</p>`,37)])])}const g=e(r,[["render",n]]);export{u as __pageData,g as default};
